SELECT 'core-2026-09-v4','phrasal-verbs','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"phrasal-verbs","title":"Phrasal verbs: meaning and object position","level":"B2","order":55,"summary":"Learn a verb and its particle together, including whether an object can split them.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["A verb plus particle can have a new meaning","Separable transitive phrasal verbs","Pronoun objects go in the middle","Inseparable and three-part verbs"],"rules":[{"title":"A verb plus particle can have a new meaning","explanation":"A phrasal verb combines a verb with an adverbial particle such as up, out or off. Its meaning may be literal or idiomatic. Learn the whole expression in context rather than trying to assign one fixed meaning to each particle.","pattern":"**Call off** a match = cancel it.","commonMistakes":["Off does not always mean remove: in call off, it contributes to the idiomatic meaning cancel."],"examples":["In “Please turn on the lamp”, what does the phrasal verb mean in this context? → **activate the lamp**","In “Please turn off the heater”, what does the phrasal verb mean in this context? → **deactivate the heater**"],"skill":"form"},{"title":"Separable transitive phrasal verbs","explanation":"With many transitive phrasal verbs, a noun object can come after the particle or between verb and particle. The 50 expressions in this bank are practised in their separable uses. A long noun object often sounds clearer after the particle.","pattern":"Turn **the light** off. / Turn off **the light**.","commonMistakes":["Not all multi-word verbs are separable; this pattern must be learned for the specific verb and meaning."],"examples":["Replace “the lamp” with “it” in this separable phrasal verb: “Please turn on the lamp.” → **turn it on**","Replace “the heater” with “it” in this separable phrasal verb: “Please turn off the heater.” → **turn it off**"],"skill":"meaning"},{"title":"Pronoun objects go in the middle","explanation":"With a separable phrasal verb, an unstressed object pronoun normally goes between verb and particle. Use turn it off, not turn off it. The verb carries tense; the particle does not change.","pattern":"She **turned it off**.","commonMistakes":["She turned off it is not the ordinary object-pronoun order for separable turn off."],"examples":["Move the noun object between verb and particle, preserving the past tense: “They turned on the lamp.” → **They turned the lamp on.**","Move the noun object between verb and particle, preserving the past tense: “They turned off the heater.” → **They turned the heater off.**"],"skill":"contrast"},{"title":"Inseparable and three-part verbs","explanation":"Prepositional verbs such as look after keep their preposition before the object: look after her. Three-part expressions such as put up with normally keep the whole sequence before the object. Some phrasal verbs are intransitive and have no object.","pattern":"Look **after her**. / Put **up with it**. / The plane **took off**.","commonMistakes":["Take off can be intransitive for a plane departing or separable for removing clothing; meaning changes its structure."],"examples":["Keep the phrasal verb after did not: “They did not **turn** on the lamp.”","Keep the phrasal verb after did not: “They did not **turn** off the heater.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-phrasal-order"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Learn a verb and its particle together, including whether an object can split them.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"A verb plus particle can have a new meaning","explanation":"A phrasal verb combines a verb with an adverbial particle such as up, out or off. Its meaning may be literal or idiomatic. Learn the whole expression in context rather than trying to assign one fixed meaning to each particle.","pattern":"**Call off** a match = cancel it.","commonMistakes":["Off does not always mean remove: in call off, it contributes to the idiomatic meaning cancel."],"examples":["In “Please turn on the lamp”, what does the phrasal verb mean in this context? → **activate the lamp**","In “Please turn off the heater”, what does the phrasal verb mean in this context? → **deactivate the heater**"],"skill":"form","id":"phrasal-verbs-foundation-1","domain":"prepositions","referenceIds":["bc-phrasal-order"],"readingVersion":"core-2026-09-v3"},{"title":"Separable transitive phrasal verbs","explanation":"With many transitive phrasal verbs, a noun object can come after the particle or between verb and particle. The 50 expressions in this bank are practised in their separable uses. A long noun object often sounds clearer after the particle.","pattern":"Turn **the light** off. / Turn off **the light**.","commonMistakes":["Not all multi-word verbs are separable; this pattern must be learned for the specific verb and meaning."],"examples":["Replace “the lamp” with “it” in this separable phrasal verb: “Please turn on the lamp.” → **turn it on**","Replace “the heater” with “it” in this separable phrasal verb: “Please turn off the heater.” → **turn it off**"],"skill":"meaning","id":"phrasal-verbs-foundation-2","domain":"prepositions","referenceIds":["bc-phrasal-order"],"readingVersion":"core-2026-09-v3"},{"title":"Pronoun objects go in the middle","explanation":"With a separable phrasal verb, an unstressed object pronoun normally goes between verb and particle. Use turn it off, not turn off it. The verb carries tense; the particle does not change.","pattern":"She **turned it off**.","commonMistakes":["She turned off it is not the ordinary object-pronoun order for separable turn off."],"examples":["Move the noun object between verb and particle, preserving the past tense: “They turned on the lamp.” → **They turned the lamp on.**","Move the noun object between verb and particle, preserving the past tense: “They turned off the heater.” → **They turned the heater off.**"],"skill":"contrast","id":"phrasal-verbs-foundation-3","domain":"prepositions","referenceIds":["bc-phrasal-order"],"readingVersion":"core-2026-09-v3"},{"title":"Inseparable and three-part verbs","explanation":"Prepositional verbs such as look after keep their preposition before the object: look after her. Three-part expressions such as put up with normally keep the whole sequence before the object. Some phrasal verbs are intransitive and have no object.","pattern":"Look **after her**. / Put **up with it**. / The plane **took off**.","commonMistakes":["Take off can be intransitive for a plane departing or separable for removing clothing; meaning changes its structure."],"examples":["Keep the phrasal verb after did not: “They did not **turn** on the lamp.”","Keep the phrasal verb after did not: “They did not **turn** off the heater.”"],"skill":"application","id":"phrasal-verbs-foundation-4","domain":"prepositions","referenceIds":["bc-phrasal-order"],"readingVersion":"core-2026-09-v3"},{"domain":"prepositions","id":"multiword-verb-types","title":"Phrasal, prepositional and phrasal-prepositional verbs","explanation":"A particle verb such as turn off may permit an object between its parts; a prepositional verb such as look after keeps its preposition before its complement. Some combinations contain both a particle and a preposition, as in put up with. Their meanings can be idiomatic, so learn meaning, transitivity and order together.","pattern":"turn **it** off / look after **it**","examples":["Please **put up with the noise** for a moment.","The engine **broke down**; it has no object here."],"commonMistakes":["A pronoun goes between a separable particle verb and particle, but not into a prepositional verb: turn it off, not look it after."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**Call off** a match = cancel it.","Turn **the light** off. / Turn off **the light**.","She **turned it off**.","Look **after her**. / Put **up with it**. / The plane **took off**."],"readingVersion":"core-2026-09-v4"},"stage":"5 · Complex sentences","prerequisites":["verb-pattern-meaning"],"readingReferenceIds":["bc-phrasal-order","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='phrasal-verbs'
